from docx.oxml import OxmlElement
from docx.oxml.ns import qn

ROOT = Path(r'C:\Users\soyel\Marihuanero')
OUT = ROOT / 'Documentacion' / 'Defensa_Marihuanero.docx'
d = Document()
sec = d.sections[0]
sec.page_width, sec.page_height = Inches(8.5), Inches(11)
sec.top_margin = sec.bottom_margin = Inches(.72)
sec.left_margin = sec.right_margin = Inches(.8)
normal = d.styles['Normal']
normal.font.name = 'Calibri'
normal.font.size = Pt(11)
normal.paragraph_format.space_after = Pt(7)
normal.paragraph_format.line_spacing = 1.08
for name, size in [('Title',26),('Subtitle',13),('Heading 1',19),('Heading 2',13)]:
    st=d.styles[name]; st.font.name='Calibri'; st.font.size=Pt(size); st.font.color.rgb=RGBColor(0,0,0)
    st.paragraph_format.space_before=Pt(10); st.paragraph_format.space_after=Pt(7)
    st.paragraph_format.keep_with_next=True
