def p(t): d.add_paragraph(t)
def h(t): d.add_heading(t,2)
def code(t):
    a=d.add_paragraph(); a.paragraph_format.space_before=Pt(3); a.paragraph_format.space_after=Pt(9)
    r=a.add_run(t); r.font.name='Consolas'; r.font.size=Pt(9)
def page(n,title):
    if n>1: d.add_page_break()
    d.add_heading(f'{n}  {title}',1)
def table(headers,rows,widths=None):
    t=d.add_table(rows=1, cols=len(headers)); t.autofit=False
    for c,s in zip(t.rows[0].cells,headers): c.text=s
    pr=t.rows[0]._tr.get_or_add_trPr(); pr.append(OxmlElement('w:tblHeader'))
    for row in rows:
        for c,s in zip(t.add_row().cells,row): c.text=s
    for i,row in enumerate(t.rows):
        for j,c in enumerate(row.cells):
            if widths: c.width=Inches(widths[j])
            tcpr=c._tc.get_or_add_tcPr(); b=OxmlElement('w:tcBorders')
            for edge in ['top','left','bottom','right']:
                e=OxmlElement('w:'+edge); e.set(qn('w:val'),'single'); e.set(qn('w:sz'),'4'); e.set(qn('w:color'),'D9D9D9'); b.append(e)
            tcpr.append(b)
            for para in c.paragraphs:
                para.paragraph_format.space_after=Pt(4)
                for r in para.runs:
                    r.font.size=Pt(10)
                    if i==0:r.bold=True

page(1,'Mi juego en pocas palabras')
d.add_paragraph('Marihuanero explicado para mi exposición','Title')
d.add_paragraph('Guía de estudio del proyecto y sus scripts','Subtitle')
p('Esta guía explica la versión guardada del proyecto Marihuanero en Unity 6.6. Está escrita para entender el juego y poder enseñarlo con tus propias palabras. No hace falta memorizar cada línea de código.')
h('Qué es y cómo se gana')
p('Es un juego de plataformas en 2D con una selva como escenario. El personaje recorre el nivel, salta entre plataformas y recoge diez hojas. Después debe tocar al Patrón que está al final. Tener las diez hojas no termina la partida por sí solo: todavía hay que llegar a la meta.')
p('Los pinchos y las caídas son los peligros. Si toco pinchos o caigo demasiado abajo, aparece la derrota. Si llego a la meta con las diez hojas, aparece la victoria. En ambos casos puedo volver a empezar.')
table(['Acción','Cómo la hago'], [('Caminar','A y D o flechas izquierda y derecha'),('Saltar','Barra espaciadora mientras estoy en el suelo'),('Empezar','Botón JUGAR en el menú'),('Volver a intentar','Botón del panel final')],[2,4.8])
h('Lo que debo saber para mañana')
p('Primero entiende el recorrido completo: menú, movimiento, hojas, peligro y final. Después aprende qué tarea tiene cada script. Al final de esta guía hay un discurso corto y preguntas para practicar. Puedes tener Unity abierto para señalar las cosas mientras explicas.')
p('La carpeta del proyecto es C:\\Users\\soyel\\Marihuanero. Los ocho scripts del juego están en Assets/Scripts. En esta revisión solo se añadieron comentarios: las instrucciones que hacen funcionar el juego siguen iguales.')

page(2,'Cómo está organizado el proyecto')
h('Las ventanas que uso en Unity')
p('Project muestra las carpetas y archivos del proyecto. Hierarchy muestra los objetos de la escena que tengo abierta. Inspector muestra las casillas y piezas del objeto seleccionado. Scene sirve para acomodar las cosas; Game muestra lo que ve la cámara del jugador.')
p('Por eso, cuando abro MenuPrincipal ya no veo las plataformas en Hierarchy. No significa que se borraron: están dentro de SampleScene. Para verlas otra vez abro esa escena desde la carpeta Scenes.')
table(['Carpeta dentro de Assets','Para qué sirve'], [('Scenes','Guarda MenuPrincipal y SampleScene'),('Scripts','Guarda las instrucciones escritas en C#'),('Imagenes','Fondos personajes suelo hojas pinchos y retratos'),('Prefabs','Guarda moldes de objetos que puedo copiar'),('Sonidos','Efectos y música de fondo'),('Materiales','Apariencia y efecto de la atmósfera'),('Settings y TextMeshPro','Ajustes de Unity y recursos para mostrar textos')],[2.2,4.6])
h('Cómo se empezó')
p('Se creó un proyecto 2D. Primero se probaron las reglas con figuras sencillas: un personaje, piso, plataformas y objetos de colores. Cuando esas reglas funcionaron, se cambiaron los dibujos por imágenes de la selva. Así no hubo que volver a programar todo para cambiar la apariencia.')
h('Las dos escenas')
p('MenuPrincipal presenta el juego y sus botones. SampleScene contiene el nivel. En Build Profiles, las dos escenas están en la lista y el menú va primero. Esto permite que el botón JUGAR abra el nivel por su nombre.')
p('Un objeto puede tener varias piezas. Por ejemplo, el jugador tiene una pieza para la física, otra para detectar choques y scripts para moverse y animarse. Unity permite unirlas en el Inspector.')

page(3,'Cómo se construyó el recorrido')
h('El dibujo y la parte que se puede tocar')
p('El Sprite Renderer enseña la imagen. El Box Collider 2D es una caja invisible que marca dónde se puede chocar o tocar. El personaje no camina sobre los colores de la imagen: se apoya sobre esa caja. Por eso hay que ajustar ambos para que los pies se vean sobre el suelo.')
p('El suelo usa tierra con césped arriba y profundidad hacia abajo. Las plataformas tienen una imagen de tierra flotante. Cambiar una imagen no reemplaza automáticamente el tamaño de la caja: eso se revisa por separado.')
h('El nivel que tengo ahora')
p('El recorrido tiene doce plataformas, diez hojas y doce grupos de pinchos. Hay dos huecos, aproximadamente entre X 24 y 29 y entre X 58 y 63. El Patrón está cerca de X 89. Arbol1 y Arbol2 sirven como límites sólidos para no salir por los extremos.')
p('X significa izquierda o derecha. Y significa altura. Z se usa para la profundidad. Las plataformas están a distintas alturas para que el jugador tenga que calcular sus saltos. El suelo tiene su parte superior cerca de Y menos 2,5.')
h('Para qué hicimos los prefabs')
p('Un prefab es un molde: guarda el dibujo, el tamaño, la caja y la etiqueta de un objeto. El administrador usa el molde de hoja y el de pinchos para crear copias al empezar. Las posiciones están guardadas en listas; así no necesitamos programar cada copia por separado.')
p('La etiqueta o Tag ayuda a reconocer qué tocamos. Hoja significa recoger; Pinchos significa perder; Meta significa comprobar si ya ganamos. La capa Suelo ayuda a reconocer dónde se puede apoyar el personaje.')
h('Cómo lo muestro en la defensa')
p('Selecciono una plataforma y señalo su Sprite Renderer y su Box Collider 2D. Luego abro un prefab y explico que es un molde. Al entrar en Play aparecen las copias de hojas y pinchos que crea el programa.')

page(4,'ControlJugador y el movimiento')
p('Este archivo va en el objeto Jugador. Su tarea es leer el teclado, mover el cuerpo, permitir el salto y avisar cuando tocamos algo importante.')
h('Primero busca lo que necesita')
p('Awake guarda el Rigidbody2D y el BoxCollider2D del personaje. El primero permite moverlo con física y gravedad; el segundo marca su caja. GetComponent significa buscar esa pieza en el mismo objeto.')
h('Después escucha el teclado')
p('Update revisa las teclas en cada imagen del juego. Al comenzar deja dirección en cero. Si pulso izquierda resta uno y si pulso derecha suma uno. Si pulso ambas, se cancelan. Si no hay teclado conectado, sale de ese bloque sin seguir leyendo teclas.')
p('Espacio deja un aviso de salto pendiente. Es como decir “quiero saltar”; el bloque de física decide si realmente se puede. Si la partida ya terminó, no sigue aceptando movimiento. También revisa si el jugador cayó por debajo de Y menos 7 para pedir la derrota.')
h('La parte que mueve de verdad')
code('cuerpo.linearVelocity = new Vector2(\n    direccion * rapidez,\n    cuerpo.linearVelocity.y\n);')
p('El primer número mueve a los lados. El segundo conserva la subida o caída que ya tenía el personaje. Si pusiera cero en el segundo número todo el tiempo, estorbaría el salto y la gravedad.')
h('Cómo sabe si puede saltar')
p('FixedUpdate hace una pequeña revisión debajo de los pies con OverlapBox. Solo busca objetos de la capa Suelo. Si hay un apoyo y el salto está pendiente, pone una velocidad hacia arriba y pide el sonido de salto. Después borra el aviso para no saltar muchas veces con una sola pulsación.')
p('En el Inspector actual, la rapidez es 5, la fuerza de salto es 10 y la gravedad es 2. Son las casillas guardadas en Unity. El número inicial escrito en el archivo puede ser distinto: cambiar ese número no siempre cambia una casilla que ya estaba guardada.')

page(5,'ControlJugador y lo que toca')
h('La entrada de los contactos')
p('OnTriggerEnter2D se ejecuta cuando el personaje entra en una zona marcada como Is Trigger. Esa zona avisa del contacto sin convertirse en una pared. El suelo normal usa una caja sólida; las hojas, los pinchos y la meta usan zonas que avisan.')
code('if (otro.CompareTag("Hoja"))')
p('CompareTag pregunta si el objeto tiene esa etiqueta. El nombre debe coincidir exactamente, incluyendo mayúsculas. No se decide por el color verde o por la forma del dibujo.')
h('Cuando toca una hoja')
p('Primero se desactiva la caja de la hoja para que el mismo contacto no la cuente dos veces. Después se llama a RecogerHoja del administrador. Finalmente se elimina esa copia del nivel con Destroy. El molde guardado en Prefabs no se borra.')
h('Cuando toca pinchos')
p('El jugador llama a Morir del administrador. El administrador controla el sonido, el panel y la pausa del nivel. El personaje no necesita repetir esas instrucciones para cada grupo de pinchos.')
h('Cuando toca la meta')
p('Llama a IntentarGanar. Ese nombre tiene sentido porque llegar al final no basta: el administrador todavía revisa cuántas hojas tenemos. Si faltan hojas, avisa y deja continuar. Si tenemos diez, muestra la victoria.')
h('Un ejemplo completo para explicar')
p('“Yo pulso D y el personaje camina. Cuando su caja toca la zona de una hoja, el script reconoce la etiqueta Hoja. Le avisa al administrador para sumar una y quitar esa copia. La cuenta cambia en la pantalla y suena el efecto. Cada parte tiene su propia tarea”.')
h('Por qué se separó así')
p('ControlJugador se ocupa del personaje. ControlNivel se ocupa de las reglas de la partida. Así, si quiero cambiar el mensaje de victoria, voy al administrador y no tengo que revisar toda la lectura del teclado.')

page(6,'ControlNivel y el comienzo de la partida')
p('ControlNivel está en AdministradorNivel. Es como el encargado del recorrido: guarda la cuenta, crea objetos y decide cuándo termina la partida.')
h('Las casillas del principio')
p('textoHojas y textoAviso son textos de pantalla. prefabHoja y prefabPinchos son los moldes. panelDerrota y panelVictoria son los letreros finales. sonidos apunta al encargado del audio. Estas conexiones se hacen arrastrando los objetos correctos al Inspector.')
p('hojasRecogidas guarda cuántas llevamos. totalHojas vale diez. Las dos marcas derrotaMostrada y victoriaMostrada recuerdan si ya terminó la partida. PartidaTerminada responde sí cuando cualquiera de las dos está encendida.')
h('Lo que hace Start')
p('Al entrar al nivel devuelve el tiempo a velocidad normal, deja el contador en cero, limpia el aviso y esconde los dos paneles finales. Después crea las hojas, crea los pinchos y escribe el contador inicial. Así cada intento comienza de la misma manera.')
h('Las listas de lugares')
code('foreach (Vector2 posicion in posicionesHojas)\n    Instantiate(prefabHoja,\n        new Vector3(posicion.x, posicion.y, 0f),\n        Quaternion.identity);')
p('foreach significa “por cada lugar de la lista”. Instantiate significa “crea una copia del molde”. Vector3 reúne X, Y y Z. Quaternion.identity deja la copia sin un giro añadido. No tienes que memorizar la palabra larga: aquí solo indica que la hoja aparece derecha.')
p('CrearHojas usa una lista con X y Y. CrearPinchos usa una lista de X y les da una misma altura de Y menos 2,2. Las listas se pueden cambiar desde el Inspector.')
h('La cuenta que veo')
p('RecogerHoja suma una, pide su sonido y llama a ActualizarContador. Este último escribe algo como Hojas: 3 / 10 en el texto conectado. La pantalla muestra la cuenta que guarda el programa; no cuenta dibujos por su cuenta.')

page(7,'ControlNivel y los dos finales')
h('Cómo funciona la victoria')
p('IntentarGanar primero revisa si la partida ya terminó. Si todavía seguimos y faltan hojas, escribe un aviso. Si ya tenemos las diez, marca victoria, reproduce el sonido, limpia el aviso, muestra PanelVictoria y detiene el tiempo del juego.')
h('Cómo funciona la derrota')
p('Morir también sale enseguida si la partida había terminado. Si no, marca derrota y pide el sonido de muerte antes de mostrar el panel y parar el tiempo. Esto evita que el mismo peligro vuelva a pedir muchas derrotas.')
code('Time.timeScale = 0f;')
p('Esta línea deja quieta la parte del juego que usa ese tiempo: movimiento y física, por ejemplo. El audio puede seguir sonando y los botones de la pantalla final siguen funcionando. Por eso se puede escuchar el meme y luego pulsar Reintentar.')
h('Cómo funciona volver a jugar')
code('Time.timeScale = 1f;\nSceneManager.LoadScene(\n    SceneManager.GetActiveScene().name\n);')
p('ReiniciarNivel vuelve a poner el tiempo normal y carga otra vez la escena actual. Al cargarse se ejecuta de nuevo Start. Por eso las hojas reaparecen y el contador vuelve a cero sin tener que devolver cada hoja a mano.')
h('Cómo conecto el botón')
p('Selecciono el botón del panel. En Button busco On Click, pulso más y arrastro AdministradorNivel al espacio del objeto. En la lista elijo ControlNivel y luego ReiniciarNivel. Debo arrastrar el objeto que tiene el script, no el archivo del script ni el propio botón.')
h('Un error que aprendimos a reconocer')
p('NullReferenceException suele indicar que una casilla necesita algo y está vacía. Por ejemplo, si textoHojas no apunta al texto de la pantalla, el programa no sabe dónde escribir. Reviso el mensaje de Console y la casilla correspondiente del Inspector.')

page(8,'AnimarJugador y los dibujos del personaje')
p('El personaje tiene un cuerpo que se mueve y una imagen que se ve. La imagen está en el hijo ImagenJugador. Esta separación permite cambiar el dibujo sin cambiar las reglas de movimiento.')
h('Cómo se prepararon las imágenes')
p('PersonajeRelajado.png reúne doce poses en una sola imagen. Unity las separa en cuadritos. Cuatro forman Quieto, cuatro Caminar y cuatro Saltar. Los archivos de animación indican qué dibujos enseñar y en qué orden. Un PNG por sí solo no guarda una animación que Unity reproduzca automáticamente.')
p('Jugador.controller tiene los tres estados. En este proyecto el script elige el estado que corresponde; no depende de una red de flechas para decidirlo. El dibujo tampoco arrastra el cuerpo: Apply Root Motion está desactivado.')
h('Qué hace cada bloque')
p('Awake guarda el cuerpo, la caja y ControlJugador. Update revisa si la partida está en pausa, lee la velocidad y comprueba el apoyo debajo de los pies. Después pasa esos datos a MostrarMovimiento.')
p('MostrarMovimiento mira si estamos en el aire, caminando o quietos. También voltea el dibujo cuando caminamos a la izquierda. Recuerda el estado anterior para no reiniciar la misma animación a cada momento.')
p('MostrarPoseSalto enseña una parte concreta de la animación. Cuando subimos muestra la pose de subida; cuando caemos, la de caída. Al tocar el piso mantiene brevemente una pose de aterrizaje, aproximadamente una décima de segundo, antes de volver a caminar o estar quieto.')
h('Lo que digo si me preguntan')
p('“La animación mira lo que el cuerpo ya está haciendo. No es la animación la que calcula el salto. Primero se mueve el cuerpo y después se elige el dibujo que combina con ese movimiento”.')
h('Cómo lo enseño')
p('Abro la carpeta de personajes y las animaciones. Luego doy Play y pruebo caminar, detenerme, saltar y cambiar de dirección. Señalo el objeto Jugador y su hijo ImagenJugador para explicar la separación.')

page(9,'La cámara y el tamaño del fondo')
h('CamaraSigue')
p('Este script está en Main Camera y tiene conectado al Jugador. OnEnable prepara el seguimiento desde cero. LateUpdate trabaja después del movimiento del personaje para colocar la cámara usando su posición más reciente.')
p('En el primer momento coloca el encuadre dos unidades delante del personaje. Después acompaña el cambio horizontal que hizo el jugador y suaviza la corrección que falte. Conserva la altura y la profundidad: no sube y baja con cada salto.')
p('Antes había una sensación de empujón hacia atrás. Se corrigió el seguimiento para acompañar el movimiento horizontal mostrado en pantalla. No se añadió una fuerza de retroceso al personaje. Además, la física del jugador usa Interpolate para que se vea más suave y detección Continuous para los contactos.')
h('El acercamiento actual')
p('La cámara es Orthographic, que muestra una vista plana apropiada para 2D. Su Size actual es 4,2. Ese número representa la mitad de la altura visible. Al bajarlo se ve menos escenario y el personaje se ve más grande. No hace falta agrandar al personaje para acercar la vista.')
h('AjustarFondo')
p('OnEnable encuentra la cámara y la imagen. LateUpdate revisa el tamaño visible. AjustarTamano calcula cuánto debe crecer el fondo para cubrir la pantalla, manteniendo sus proporciones. También tiene en cuenta el tamaño del objeto padre.')
p('Elige el aumento que alcance a cubrir tanto el ancho como el alto. Por eso puede quedar una parte de la imagen fuera de la pantalla: es preferible a mostrar un borde vacío. Solo cambia la escala cuando hace falta.')
h('Dónde se usa')
p('AjustarFondo sirve para el fondo del nivel y para FondoPortada del menú. CamaraSigue pertenece a la cámara del nivel. La cámara del menú muestra su presentación y no persigue al jugador.')

page(10,'La selva y su ambiente animado')
h('Lo que realmente se animó')
p('El nivel combina una imagen de selva con una capa transparente de niebla, luces y puntitos. No se puso un GIF de diez segundos. El efecto se dibuja con un material y se repite suavemente para dar vida al fondo.')
h('AnimarSelva')
p('OnEnable busca la capa que dibuja el efecto y prepara sus valores. LateUpdate va avanzando un reloj mientras jugamos. El ciclo está pensado para repetirse cada diez segundos. Cuando termina la partida, el tiempo del juego se detiene y el ambiente deja de avanzar.')
p('ActualizarCapa hace que esa capa cubra la cámara. Usa un suelo de referencia para saber dónde está el piso y colocar la niebla a una altura coherente. Así la niebla no queda en cualquier lugar cuando cambia el encuadre.')
p('El script manda al material la fase del ciclo, la forma de la pantalla, la cantidad de niebla, la intensidad de rayos, el brillo de partículas y sus colores. MaterialPropertyBlock es una forma de cambiar esos valores sin fabricar un material nuevo a cada momento. OnDisable limpia los valores que aplicó a la capa.')
h('El archivo AtmosferaSelva shader')
p('Un shader es una receta para pintar. Este dibuja una capa transparente. Sus pequeñas funciones Azar, Ruido y Nube crean variaciones para que la niebla no sea un rectángulo de color plano. La parte final combina esa niebla, haces de luz y puntos que se mueven en un ciclo.')
p('No cambia dónde se puede caminar y no empuja al personaje. Solo cambia lo que se ve. Tampoco es una película: el efecto se calcula mientras el juego está funcionando.')
h('La diferencia con el menú')
p('El menú actual usa la portada que proporcionaste. La niebla de selva pertenece al nivel; no es el fondo antiguo del menú. El archivo AjustarFondo ayuda a que la portada cubra la vista sin deformarla.')

page(11,'SonidosJuego y la música')
h('Dos reproductores con trabajos distintos')
p('Un AudioClip es una grabación guardada. Un AudioSource es el reproductor que la hace sonar. SonidosJuego usa un reproductor para efectos y tiene una conexión aparte con la música del nivel. Esto permite cortar la música al ganar o perder.')
p('Awake prepara el reproductor de efectos para que no empiece solo y para que se escuche sin depender de la distancia. También pide cargar las grabaciones con anticipación. Saltar y RecogerHoja reproducen su efecto si la partida sigue activa y hay una grabación conectada.')
h('Los archivos que se usan')
table(['Momento','Archivo y comportamiento'], [('Salto','SaltoBoing.wav efecto corto'),('Hoja','RecogerHoja.wav efecto de recogida'),('Derrota','DerrotaOofInmediato.wav sonido de muerte'),('Victoria','VictoriaPerrito.wav frase de celebración'),('Durante el nivel','MusicaArcade.wav se repite de fondo')],[1.4,5.4])
h('Cómo se evita el retraso de la muerte')
p('El archivo de derrota tenía silencio al principio. Se preparó una copia recortada para que el sonido empiece al recibir la orden. Morir pide el sonido antes de mostrar el panel. No se usó una espera programada para retrasarlo.')
p('Perder y Ganar llaman al mismo bloque ReproducirResultado. Ese bloque recuerda que ya terminó, detiene la música, corta un efecto que estuviera sonando y reproduce el resultado una sola vez. Así no se acumulan varios memes por un mismo contacto.')
h('La canción de fondo')
p('MusicaDelNivel tiene un AudioSource que empieza al cargar el nivel, se repite y está a volumen bajo. Al reiniciar la escena vuelve a comenzar. Es Level 3 del paquete Retro Game Music Pack de Juhani Junkala, con licencia CC0. No es una canción de Metal Slug. La hoja tampoco usa una canción de Snoop Dogg en esta versión.')
p('La licencia y el origen de la música están guardados en Documentacion/Licencia_musica_arcade.txt. Los efectos y memes tienen otros orígenes; no hay que presentar todos los recursos como si fueran hechos a mano o tuvieran la misma licencia.')

page(12,'El menú principal y sus botones')
h('Cómo se armó la pantalla')
p('Se creó MenuPrincipal aparte del nivel. Tiene una cámara, AdministradorMenu, un Canvas con imágenes y botones, y SistemaDeEventos para recibir los clics. El Canvas organiza las cosas que van encima de la vista del juego.')
p('La portada actual se llama PortadaMarihuanero.jpg y fue proporcionada por ti. Se muestra completa en una parte de la composición y también se usa ampliada y oscurecida como fondo. El contenido del menú acompaña esa imagen. El lema visible dice PLATA O PLOMO y el botón principal dice JUGAR.')
h('ControlMenuPrincipal')
p('Awake devuelve el tiempo a velocidad normal y deja el cursor visible y libre. Esto evita entrar al menú con el tiempo detenido por un final anterior. La casilla escenaJuego guarda el nombre SampleScene.')
p('Jugar usa una marca llamada cargando para ignorar un segundo clic mientras empieza a abrir el nivel. Después pone el tiempo normal y carga SampleScene. Para que funcione, el nombre debe coincidir con la escena y esta debe estar incluida en Build Profiles.')
code('SceneManager.LoadScene(escenaJuego);')
p('Salir hace dos cosas según dónde estemos: dentro del editor detiene Play; dentro del juego exportado pide cerrar la aplicación. El bloque que contiene UNITY_EDITOR separa esos dos casos.')
h('Lo que todavía no hace')
p('NIVELES está como botón de presentación y no tiene una acción conectada. No abre un selector de niveles. Es algo que se puede desarrollar después. El nombre interno BotonPlataOPlomo puede seguir apareciendo en Hierarchy, aunque el texto que ve el jugador ya diga JUGAR.')
h('Cómo lo enseño')
p('Abro MenuPrincipal y selecciono el botón JUGAR. En On Click muestro la conexión con AdministradorMenu y el método Jugar. Después doy Play, pulso el botón y enseño que abre la otra escena.')

page(13,'Los textos y las pantallas finales')
h('El contador de hojas')
p('El contador está dentro de Canvas, en un panel colocado arriba a la izquierda. Incluye el dibujo de una hoja y un texto de TextMeshPro. El programa cambia el contenido del texto; el color, tamaño y lugar se ajustan en el Inspector.')
p('Los anclajes o Anchors indican a qué zona de la pantalla se pega el objeto. Por eso el contador usa la esquina superior izquierda. El Canvas Scaler ayuda a conservar la composición con distintas ventanas usando una referencia de 1920 por 1080.')
h('Derrota y victoria')
p('Los dos paneles cubren la pantalla y oscurecen el nivel para que el resultado se lea bien. Tienen una imagen del Patrón, un mensaje y un botón. El de derrota muestra ELEGISTE PLOMO y el de victoria felicita por completar el recorrido.')
p('ControlNivel los esconde al empezar y muestra el correcto al terminar. Los botones llaman a ReiniciarNivel. Ocultar un panel con SetActive(false) no lo borra; solo deja de mostrarse hasta que el programa vuelva a activarlo.')
h('Cómo se conecta una casilla')
p('Primero selecciono el objeto que tiene el script, por ejemplo AdministradorNivel. Después busco el campo panelVictoria y arrastro PanelVictoria desde Hierarchy. Para un campo de texto arrastro el objeto que tiene el texto de TextMeshPro. Para un molde arrastro el prefab desde Project.')
h('Reglas para trabajar sin perder cambios')
p('Detengo Play antes de editar lo que quiero guardar. Guardo la escena con Ctrl más S y guardo los archivos de código en el editor. Los cambios hechos durante Play suelen volver a su estado anterior cuando detengo la prueba.')
p('Si aparece New Text, selecciono el texto correcto y cambio Text Input. Si una llave del código falta, Console señala un error de escritura. Si el juego no responde como esperaba, primero miro Console y luego las conexiones del Inspector.')

page(14,'Cómo trabajan juntos los archivos')
h('El viaje de una partida')
p('1. Abro MenuPrincipal. ControlMenuPrincipal prepara el cursor y JUGAR abre SampleScene.')
p('2. ControlNivel prepara una partida limpia. Crea las hojas y pinchos desde sus moldes. La música del nivel empieza a repetirse.')
p('3. ControlJugador lee las teclas y mueve el cuerpo. AnimarJugador escoge la pose. CamaraSigue acompaña el recorrido. AjustarFondo y AnimarSelva mantienen el ambiente visual.')
p('4. Si recojo una hoja, ControlJugador reconoce la etiqueta y avisa a ControlNivel. El administrador suma una, cambia el texto y pide el sonido a SonidosJuego.')
p('5. Si toco pinchos o caigo, ControlNivel decide derrota. Si toco la meta con diez hojas, decide victoria. SonidosJuego corta la música y reproduce el resultado. El panel aparece y el tiempo se detiene.')
p('6. El botón vuelve a cargar la escena. Se ejecuta la preparación inicial y comienza otro intento.')
h('Lo que ya se corrigió durante el desarrollo')
p('Se ajustaron suelo y plataformas para que el dibujo coincida con el apoyo. Se usó un material sin fricción para evitar quedarse pegado a los lados. Se corrigió el seguimiento de cámara para reducir el tirón al saltar. Se recortó el silencio inicial del sonido de derrota. Los pinchos recibieron una imagen más agresiva conservando su zona de contacto.')
h('Qué hace esta entrega de documentación')
p('Los ocho scripts de Assets/Scripts recibieron comentarios por bloques con palabras sencillas. Se compararon las instrucciones antes y después de comentar y resultaron iguales. También quedó un respaldo de los originales en Documentacion/RespaldoScriptsAntesDeComentarios.')
h('Qué puedo presentar como mejoras futuras')
p('Un selector de niveles real, pausa, regreso al menú desde los resultados y más recorridos. No debo decir que NIVELES ya funciona ni que se probó una exportación completa si todavía no la he realizado. La base jugable y la presentación son distintas de esas mejoras pendientes.')

page(15,'Mi explicación para la exposición')
p('Puedes practicar este texto en voz alta y cambiar las palabras para que suene a ti. Está pensado para unos tres o cuatro minutos con pausas cortas para señalar Unity.')
h('Presento el objetivo')
p('“Mi videojuego se llama Marihuanero. Es un juego de plataformas en 2D ambientado en una selva. La idea es recorrer el nivel, recoger diez hojas y llegar al Patrón. Si caigo en un hueco o toco los pinchos, pierdo y puedo volver a intentar”.')
h('Muestro cómo lo organicé')
p('“Usé Unity y separé el menú del nivel en dos escenas. En Project tengo carpetas para imágenes, sonidos, scripts y prefabs. Un prefab es un molde que permite crear varios objetos iguales. Por ejemplo, las hojas aparecen a partir de un solo molde”.')
h('Explico el personaje y las reglas')
p('“ControlJugador lee A, D, las flechas y espacio. El cuerpo tiene gravedad y una caja para los contactos. El salto solo se permite cuando encuentra suelo debajo de los pies. AnimarJugador cambia los dibujos según si está quieto, caminando o saltando”.')
p('“ControlNivel guarda cuántas hojas llevo. Cuando toco una, suma una y actualiza el contador. Al tocar la meta revisa si ya tengo diez. También muestra victoria o derrota y permite reiniciar la partida”.')
h('Explico la presentación')
p('“La cámara sigue al personaje a los lados. El fondo se ajusta a la pantalla y la selva tiene una capa de niebla y luces. SonidosJuego reproduce los efectos. La música acompaña el nivel y se detiene cuando termina la partida para que se escuche el resultado”.')
h('Cierro con lo aprendido')
p('“Aprendí a separar lo que se ve de lo que se puede tocar, a conectar objetos con scripts y a revisar los mensajes de error. También entendí que el dibujo de un personaje no lo mueve por sí solo. Como siguiente mejora haría que el botón NIVELES permita escoger otros recorridos”.')
p('Si preguntan por la ayuda recibida, responde con sinceridad: hubo asistencia para código y recursos visuales. Tu defensa debe demostrar que entiendes cómo están conectados, cómo se prueban y qué puedes cambiar.')

page(16,'Preguntas que me pueden hacer')
h('Por qué usaste varios scripts')
p('Porque cada uno tiene una tarea. Uno mueve, otro cuenta, otro anima y otro reproduce sonidos. Así puedo encontrar más fácil dónde cambiar algo.')
h('Cómo sabe que recogiste una hoja')
p('La caja del personaje entra en la zona de la hoja. El programa reconoce la etiqueta Hoja, suma una en el administrador y elimina esa copia.')
h('Cómo evitas ganar antes de tiempo')
p('La meta llama a IntentarGanar. Allí se compara la cuenta con diez. Si faltan hojas, solo muestra un aviso.')
h('Cómo evitas saltar en el aire')
p('Se revisa una caja pequeña debajo de los pies. Si no encuentra la capa Suelo, no se acepta el salto pendiente.')
h('Qué diferencia hay entre Update y FixedUpdate')
p('Update escucha al jugador mientras se dibuja el juego. FixedUpdate hace los cambios del cuerpo siguiendo los pasos de la física. LateUpdate coloca la cámara después de esos movimientos.')
h('Qué diferencia hay entre una imagen y un collider')
p('La imagen es lo que veo. El collider es la forma invisible que Unity usa para saber dónde se toca algo. Pueden tener tamaños distintos, por eso hay que ajustarlos.')
h('Qué pasa cuando reinicias')
p('El tiempo vuelve a uno y se carga otra vez la escena. Start pone la cuenta en cero, esconde los paneles y vuelve a crear los objetos.')
h('Por qué no se ven plataformas al abrir el menú')
p('Porque Hierarchy solo muestra la escena abierta. Las plataformas siguen en SampleScene. Abrir MenuPrincipal no las elimina.')
h('Para qué sirven los comentarios nuevos')
p('Explican qué hace cada bloque con palabras sencillas. Las líneas que empiezan con dos barras no se ejecutan. Ayudan a estudiar sin cambiar las reglas del juego.')

page(17,'Repaso final antes de presentar')
h('Palabras que sí debo entender')
table(['Palabra','Cómo la explico fácil'], [('Variable','Un espacio donde guardo un dato como la cuenta de hojas'),('Método','Un grupo de instrucciones con un nombre para pedir una tarea'),('Condición if','Una pregunta que decide si hacemos algo'),('Bucle foreach','Repetir una tarea para cada elemento de una lista'),('public','Permite que otras partes usen ese dato y puede mostrar una casilla'),('private','Dato que se maneja dentro de ese script'),('GameObject','Un objeto del juego que puede tener varias piezas'),('Componente','Una de esas piezas como cámara caja o sonido'),('Trigger','Una zona que avisa que entramos sin ser una pared'),('Referencia','Una conexión hacia el objeto que otro bloque necesita')],[1.4,5.4])
h('Ensayo de cinco minutos')
p('Abro MenuPrincipal y explico JUGAR. Camino y salto. Recojo una hoja y señalo el contador. Toco un peligro para mostrar derrota y el botón de reintento. Después enseño en el código la revisión de diez hojas para explicar la victoria sin depender de completar todo el nivel durante la exposición.')
p('Antes de comenzar, compruebo que el audio se escucha a un volumen cómodo, que no hay errores rojos y que tengo abiertas las carpetas Scripts y Scenes. Guardo y salgo de Play para comenzar desde el menú.')
h('Si se me olvida una respuesta')
p('Busco la tarea por su nombre: movimiento en ControlJugador, reglas en ControlNivel, dibujos en AnimarJugador, cámara en CamaraSigue, fondo en AjustarFondo y AnimarSelva, audio en SonidosJuego y menú en ControlMenuPrincipal. Explico el bloque con calma y señalo el objeto conectado.')
p('Lo más valioso no es recitar el código: es poder mostrar qué dato entra, qué decisión toma el programa y qué cambia en la pantalla.')

